350:/**
351: * A paint in square cells `size` meters across. Each surface point is taken to the face orientation (±x, ±y, ±z)
352: * its normal is closest to and snapped to that face's cell grid, so cells stay square on boxes and tubes alike.
353: * `fn` returns the cell's colour (any colour or paint); `c.pick(ramp, value)` picks a ramp step, dithered with the
354: * 4 × 4 Bayer pattern when `dither` is true.
355: */
356:export function cellPaint(size: number, fn: (c: Cell) => ColorInput, options: { dither?: boolean } = {}): Paint {
357:  if (!(size > 0)) throw new Error(`cellPaint(): size ${size} must be positive`);
358:  const dither = options.dither ?? false;
359:  return paint((p, n, s) => {
360:    const ax = Math.abs(n.x);
361:    const ay = Math.abs(n.y);
362:    const az = Math.abs(n.z);
363:    const axis: 0 | 1 | 2 = ay >= ax && ay >= az ? 1 : ax >= az ? 0 : 2;
364:    const q = [p.x / size, p.y / size, p.z / size];
365:    const idx = q.map((c, k) => (k === axis ? Math.floor(c + DEPTH_SHIFT) : Math.floor(c)));
366:    const centre = idx.map((c, k) => (c + 0.5 - (k === axis ? DEPTH_SHIFT : 0)) * size);
367:    const u = axis === 0 ? idx[2] : idx[0];
368:    const v = axis === 1 ? idx[2] : idx[1];
369:    const cell = new Cell(
370:      new Vector3(centre[0], centre[1], centre[2]),
371:      u,
372:      v,
373:      idx[axis],
374:      axis,
375:      n,
376:      s,
377:      dither ? bayer(u, v) : 0.5,
378:    );
379:    return fn(cell);
380:  });
381:}
